#!/usr/bin/env node
/* Copies the DIPAI-generated architecture artifact into
 * lib/generated/architecture.json (committed, like the docs search index, so
 * the Architecture Explorer works on Vercel with zero runtime fs access).
 *
 * One-command regeneration from the DIPAI checkout:
 *   node scripts/sync-arch-artifact.mjs [source.json]
 *
 * Default source: ../ui/tests/fixtures/archmeta_v1.json (DIPAI checkout as a
 * sibling of this repo). The artifact is generated by:
 *   python -m dipai.archmeta --config configs/scratch.yaml -o <path>
 */

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const defaultSource = path.resolve(root, "..", "ui", "tests", "fixtures", "archmeta_v1.json");
const source = path.resolve(process.argv[2] ?? defaultSource);
const outDir = path.join(root, "lib", "generated");
const outPath = path.join(outDir, "architecture.json");

function fail(message) {
  console.error(`sync-arch-artifact: ${message}`);
  process.exit(1);
}

if (!fs.existsSync(source)) fail(`source not found: ${source}`);

let artifact;
try {
  artifact = JSON.parse(fs.readFileSync(source, "utf8"));
} catch (err) {
  fail(`source is not valid JSON: ${err.message}`);
}

if (artifact.schema !== "dipai-archmeta") {
  fail(`expected schema "dipai-archmeta", got ${JSON.stringify(artifact.schema)}`);
}
if (artifact.schema_version !== 1) {
  fail(`expected schema_version 1, got ${JSON.stringify(artifact.schema_version)}`);
}
if (!Array.isArray(artifact.components) || artifact.components.length === 0) {
  fail("components must be a non-empty array");
}
if (typeof artifact.params?.total !== "number") {
  fail("params.total must be a number");
}

fs.mkdirSync(outDir, { recursive: true });
fs.writeFileSync(outPath, `${JSON.stringify(artifact, null, 2)}\n`, "utf8");

const bytes = fs.statSync(outPath).size;
if (bytes > 2 * 1024 * 1024) fail(`written artifact is ${bytes} bytes — over the 2 MB import cap`);

console.log(
  `sync-arch-artifact: ${path.relative(root, source)} -> ${path.relative(root, outPath)} ` +
    `(${artifact.components.length} components, ${artifact.params.total.toLocaleString("en-US")} params, ${bytes} bytes)`
);
